    class: ['old:0', SH('ตัวอย่างที่ 2: แปลงเลขฐานสิบเป็นฐานสอง', 'แปลง 45 เป็นเลขฐานสอง', ['เลขฐานสิบ 45'], ['เลขฐานสอง'],
      'หารด้วย 2 ซ้ำ ๆ จดเศษไว้ทุกครั้ง แล้วอ่านเศษจากล่างขึ้นบน ซึ่งเป็นอัลกอริทึมที่ตรงกับผังงานแบบลูปของการหารซ้ำ',
      [{ w: '45 ÷ 2 = 22 เศษ 1\n22 ÷ 2 = 11 เศษ 0\n11 ÷ 2 = 5 เศษ 1\n5 ÷ 2 = 2 เศษ 1\n2 ÷ 2 = 1 เศษ 0\n1 ÷ 2 = 0 เศษ 1', s: 'หารด้วย 2 ต่อเนื่องจนผลหารเป็นศูนย์ และจดเศษทุกครั้ง' }, { w: 'อ่านเศษจากล่างขึ้นบน : 1 0 1 1 0 1\n45 = 101101₂', s: 'อ่านเศษจากล่างขึ้นบนได้ 101101 ตรวจด้วย 32 + 8 + 4 + 1 เท่ากับ 45 ถูกต้อง', hl: true }], '101101₂', 'ตรวจเลขฐานสองด้วยการบวกค่าประจำหลัก : 32 + 8 + 4 + 1 = 45')],
    exam: [SH('ตัวอย่างข้อสอบ: การไล่ค่าของอัลกอริทึมแบบมีเงื่อนไข', 'อัลกอริทึม ตั้งต้น n = 6 และ count = 0 ทำซ้ำขณะที่ n ≠ 1 ถ้า n เป็นเลขคู่ ให้ n = n ÷ 2 มิฉะนั้นให้ n = 3n + 1 แล้ว count = count + 1 เมื่อจบ ค่า count เป็นเท่าใด และค่า n สูงสุดที่เกิดขึ้นเป็นเท่าใด', ['n เริ่มต้น = 6', 'เลขคู่ : n ← n/2 , เลขคี่ : n ← 3n + 1', 'จบเมื่อ n = 1'], ['count เมื่อจบ', 'ค่า n สูงสุด'],
      'โจทย์อัลกอริทึมให้ไล่ค่าทีละรอบในตารางติดตามตัวแปร อย่าพยายามเดาผลจากหน้าตาของคำสั่ง จดค่า n ก่อนและหลังทุกรอบ แล้วนับรอบที่ทำจริง',
      [{ w: 'รอบ 1 : n = 6 (คู่) → 3 , count = 1\nรอบ 2 : n = 3 (คี่) → 10 , count = 2', s: 'เริ่มที่ 6 เป็นเลขคู่ หารสองได้ 3 จากนั้น 3 เป็นเลขคี่ ได้ 3 × 3 + 1 เท่ากับ 10' }, { w: 'รอบ 3 : 10 → 5 , count = 3\nรอบ 4 : 5 → 16 , count = 4', s: '10 เป็นคู่หารสองได้ 5 แล้ว 5 เป็นคี่ ได้ 16' }, { w: 'รอบ 5 : 16 → 8 , count = 5\nรอบ 6 : 8 → 4 , count = 6', s: 'จากนั้นเป็นเลขคู่ติดกันหลายครั้ง หารสองลงมาเรื่อย ๆ' }, { w: 'รอบ 7 : 4 → 2 , count = 7\nรอบ 8 : 2 → 1 , count = 8', s: 'ถึง 1 แล้วเงื่อนไข n ≠ 1 เป็นเท็จ ลูปหยุด' }, { w: 'count = 8\nลำดับค่า : 6, 3, 10, 5, 16, 8, 4, 2, 1\nn สูงสุด = 16', s: 'จำนวนรอบที่ทำคือ 8 และค่าที่ใหญ่ที่สุดที่เกิดขึ้นคือ 16', hl: true }], 'count = 8 ; n สูงสุด = 16', 'ใช้ตารางติดตามค่าตัวแปรทีละรอบ และตรวจว่าเงื่อนไขหยุดตรงกับที่อ่านโจทย์')],
    olym: [SH('โจทย์สอวน: ลูปซ้อนและจำนวนการวน', 'อัลกอริทึม ตั้งต้น s = 0 สำหรับ i จาก 1 ถึง 4 ทำ: สำหรับ j จาก i ถึง 4 ทำ: s = s + i × j จงหาค่า s ที่ได้ และจำนวนครั้งที่คำสั่ง s = s + i × j ถูกทำ และถ้าเปลี่ยนจาก 4 เป็น n จำนวนครั้งที่ทำเป็นเท่าใดในรูปของ n', ['i = 1..4', 'j = i..4', 's = s + i × j'], ['s สุดท้าย', 'จำนวนครั้งของการบวก', 'สูตรจำนวนครั้งเมื่อเป็น n'],
      'ลูปซ้อนที่ลูปในขึ้นกับลูปนอก ต้องไล่เป็นรอบตามค่า i ทีละค่า แล้วนับรอบของ j ในแต่ละค่า i จากนั้นสังเกตรูปแบบของจำนวนรอบเพื่อหาสูตรทั่วไป ซึ่งเป็นพื้นฐานของการวิเคราะห์ความซับซ้อนของโปรแกรม',
      [{ w: 'i = 1 : j = 1..4 → 1(1 + 2 + 3 + 4) = 10\ni = 2 : j = 2..4 → 2(2 + 3 + 4) = 18', s: 'เมื่อ i เท่ากับ 1 ผลบวกของ i คูณ j คือ 1 คูณ 10 เท่ากับ 10 เมื่อ i เท่ากับ 2 ได้ 2 คูณ 9 เท่ากับ 18' }, { w: 'i = 3 : j = 3..4 → 3(3 + 4) = 21\ni = 4 : j = 4 → 4(4) = 16', s: 'เมื่อ i เท่ากับ 3 ได้ 3 คูณ 7 เท่ากับ 21 และเมื่อ i เท่ากับ 4 ได้ 4 คูณ 4 เท่ากับ 16' }, { w: 's = 10 + 18 + 21 + 16 = 65', s: 'รวมทั้งสี่รอบของลูปนอกได้ 65', hl: true }, { w: 'จำนวนครั้ง : i = 1 → 4 ครั้ง , i = 2 → 3 , i = 3 → 2 , i = 4 → 1\n4 + 3 + 2 + 1 = 10', s: 'ลูปในทำงานรอบเยอะสุดเมื่อ i น้อย นับได้ 4, 3, 2, 1 รวมเป็น 10 ครั้ง' }, { w: 'ทั่วไป : n + (n − 1) + … + 1 = n(n + 1)/2\nn = 100 → 5050 ครั้ง', s: 'ถ้าลูปไปถึง n จำนวนครั้งคือผลบวก n ถึง 1 เท่ากับ n(n + 1)/2 ซึ่งโตตามกำลังสองของ n นั่นคือเหตุผลที่ลูปซ้อนสองชั้นช้าลงอย่างรวดเร็วเมื่อข้อมูลมาก', hl: true }], 's = 65 ; ทำ 10 ครั้ง ; n(n + 1)/2 ครั้ง', 'ลูปซ้อนที่ลูปในเริ่มจาก i → จำนวนครั้งรวมเป็นผลบวกของเลขลดหลั่น = n(n + 1)/2')]
